#pragma once
#include <QCryptographicHash>
#include <QJsonArray>
#include <QJsonDocument>
#include <QJsonObject>
#include <QRegularExpression>
#include <QSet>
#include <QStringList>
#include <algorithm>
#include <cstring>
#include <stdexcept>
namespace watchlistWorkspace {
inline void need(bool ok,const QString& why){if(!ok)throw std::runtime_error(why.toStdString());}
inline QString text(const QJsonObject&o,const QString&k){need(o.value(k).isString(),k+"需明确文本");return o.value(k).toString();}
inline QString quote(QString s){auto b=QJsonDocument(QJsonArray{s}).toJson(QJsonDocument::Compact);return QString::fromUtf8(b.mid(1,b.size()-2));}
inline QString canonical(QJsonValue v){if(v.isNull()||v.isUndefined())return "null";if(v.isBool())return v.toBool()?"true":"false";if(v.isString())return quote(v.toString());if(v.isDouble()){double n=v.toDouble();quint64 bits;std::memcpy(&bits,&n,8);return "@"+QString::number(bits,16).rightJustified(16,'0');}QStringList parts;if(v.isArray()){for(auto x:v.toArray())parts<<canonical(x);return "["+parts.join(',')+"]";}auto o=v.toObject();auto keys=o.keys();std::sort(keys.begin(),keys.end());for(auto k:keys)parts<<quote(k)+":"+canonical(o.value(k));return "{"+parts.join(',')+"}";}
inline QString hash(QJsonValue v){return QString::fromLatin1(QCryptographicHash::hash(canonical(v).toUtf8(),QCryptographicHash::Sha256).toHex());}
inline bool equal(QJsonValue a,QJsonValue b){return canonical(a)==canonical(b);}
inline bool fullId(QString id){return QRegularExpression("^(SH|SZ|BJ):(stock|index|etf):[0-9]{6}$").match(id).hasMatch();}
inline void label(QString s){need(!s.trimmed().isEmpty()&&s==s.trimmed()&&s.size()<=60&&!s.contains(QRegularExpression("[\\x00-\\x1f\\x7f]")),"名称需1至60字且无首尾空格或控制字符");}
inline void color(QString s){need(s.isEmpty()||QRegularExpression("^#[0-9A-Fa-f]{6}$").match(s).hasMatch(),"识别色需空或#RRGGBB");}
inline QSet<QString> ids(QJsonValue v,bool instrument=false){need(v.isArray(),"成员清单缺失");QSet<QString> out;need(v.toArray().size()<=3000,"成员超过3000");for(auto x:v.toArray()){need(x.isString()&&!x.toString().isEmpty()&&(!instrument||fullId(x.toString()))&&!out.contains(x.toString()),"成员身份无效或重复");out.insert(x.toString());}return out;}
inline QJsonObject validate(QJsonObject s){need(text(s,"schema")=="watchlist-workspace/v1","快照格式不支持");auto rev=text(s,"revision");need(!rev.trimmed().isEmpty()&&rev.size()<=256,"需明确管理配置版本");need(s.value("instruments").isArray()&&s.value("groups").isArray(),"完整目录或分组缺失");auto primary=ids(s.value("mainIds"),true);QSet<QString> roster;need(s.value("instruments").toArray().size()<=3000,"完整目录超过3000");for(auto v:s.value("instruments").toArray()){need(v.isObject(),"目录记录无效");auto r=v.toObject();auto id=text(r,"id");need(fullId(id)&&!roster.contains(id)&&!r.value("transient").toBool(),"目录身份重复或临时观察不可提升");auto name=text(r,"name");need(!name.trimmed().isEmpty()&&name.size()<=128,"目录名称无效");if(r.contains("symbol")){auto p=id.split(':');need(text(r,"symbol")==p[0].toLower()+p[2],"目录symbol与完整身份冲突");}roster.insert(id);}need(roster==primary,"完整目录与主自选不一致");auto groups=s.value("groups").toArray();need(groups.size()<=500,"分组超过500");QSet<QString> keys;for(auto v:groups){need(v.isObject(),"分组记录无效");auto g=v.toObject();auto id=text(g,"groupId");need(!id.trimmed().isEmpty()&&id.size()<=256&&!keys.contains(id),"分组身份无效或重复");keys.insert(id);label(text(g,"name"));color(text(g,"color"));need(g.value("readOnly").isBool(),"分组只读状态未明确");auto members=ids(g.value("memberIds"),true);for(auto m:members)need(primary.contains(m),"分组成员不在主自选完整目录");}return s;}
inline QJsonObject management(QJsonObject s){validate(s);QJsonArray roster;for(auto v:s.value("instruments").toArray()){auto r=v.toObject();QJsonObject i{{"id",r.value("id")},{"name",r.value("name")}};if(r.contains("symbol"))i["symbol"]=r.value("symbol");roster.append(i);}return {{"schema",s.value("schema")},{"revision",s.value("revision")},{"mainIds",s.value("mainIds")},{"groups",s.value("groups")},{"instruments",roster}};}
inline QString fingerprint(QJsonObject s){auto m=management(s);m.remove("revision");return hash(m);}
inline int groupIndex(QJsonArray gs,QString id){for(int i=0;i<gs.size();i++)if(gs[i].toObject().value("groupId")==id)return i;return -1;}
inline QJsonArray move(QJsonArray a,int from,int to){need(from>=0&&from<a.size()&&to>=0&&to<a.size(),"排序位置已失效");auto v=a.takeAt(from);a.insert(to,v);return a;}
inline QJsonObject apply(QJsonObject s,QJsonObject op){validate(s);auto kind=text(op,"op"),id=text(op,"groupId");auto gs=s.value("groups").toArray();int i=groupIndex(gs,id);if(kind=="addGroup"){need(i<0,"新分组身份已存在");gs.append(QJsonObject{{"groupId",id},{"name",text(op,"name")},{"color",text(op,"color")},{"readOnly",false},{"memberIds",QJsonArray{}}});}else{need(i>=0,"分组不存在");auto g=gs[i].toObject();need(!g.value("readOnly").toBool(),"此来源分组只读，未写云端或本地副本");if(kind=="deleteGroup")gs.removeAt(i);else if(kind=="moveGroup"){need(op.value("to").isDouble()&&op.value("to").toDouble()==op.value("to").toInt(-1),"排序位置需整数");gs=move(gs,i,op.value("to").toInt(-1));}else{if(kind=="renameGroup")g["name"]=text(op,"name");else if(kind=="setColor")g["color"]=text(op,"color");else{auto ms=g.value("memberIds").toArray();auto mid=text(op,"instrumentId");need(ids(s.value("mainIds"),true).contains(mid),"证券必须是当前主自选完整身份");int at=-1;for(int k=0;k<ms.size();k++)if(ms[k]==mid)at=k;if(kind=="addMember"){need(at<0,"此证券已在该组；不会去重其它组");ms.append(mid);}else if(kind=="removeMember"){need(at>=0,"成员已不在该组");ms.removeAt(at);}else if(kind=="moveMember"){need(op.value("to").isDouble()&&op.value("to").toDouble()==op.value("to").toInt(-1),"成员排序位置需整数");ms=move(ms,at,op.value("to").toInt(-1));}else need(false,"操作不支持");g["memberIds"]=ms;}gs.replace(i,g);}}s["groups"]=gs;return validate(s);}
inline void transition(QJsonObject base,QJsonObject draft){validate(base);validate(draft);need(equal(base.value("mainIds"),draft.value("mainIds"))&&equal(base.value("instruments"),draft.value("instruments")),"分组操作不得改主自选或报价原文");auto a=base;auto b=draft;a.remove("groups");b.remove("groups");need(equal(a,b),"分组操作不得改快照其它元数据");auto old=base.value("groups").toArray(),next=draft.value("groups").toArray();for(auto v:old){auto g=v.toObject();int at=groupIndex(next,g.value("groupId").toString());if(g.value("readOnly").toBool())need(at>=0&&equal(g,next[at]),"只读来源分组被修改");if(at>=0){auto before=g,after=next[at].toObject();for(auto k:{"name","color","memberIds"}){before.remove(k);after.remove(k);}need(equal(before,after),"分组身份/来源/只读元数据不得重写");}}for(auto v:next){auto g=v.toObject();if(groupIndex(old,g.value("groupId").toString())<0){need(!g.value("readOnly").toBool(),"新增本地组不得伪造只读来源");auto keys=g.keys();std::sort(keys.begin(),keys.end());need(keys==QStringList{"color","groupId","memberIds","name","readOnly"},"新组含非本模块字段");}}}
inline QJsonObject prepare(QJsonObject base,QJsonObject draft,QJsonObject current){transition(base,draft);validate(current);need(text(current,"revision")==text(base,"revision")&&fingerprint(current)==fingerprint(base),"自选配置或证券目录已并发变化；保留草稿，请重读后重做");QJsonArray changes,old=base.value("groups").toArray(),next=draft.value("groups").toArray(),beforeOrder,afterOrder;for(auto v:old)beforeOrder.append(v.toObject().value("groupId"));for(auto v:next)afterOrder.append(v.toObject().value("groupId"));for(auto v:old){auto g=v.toObject();auto id=g.value("groupId").toString();int at=groupIndex(next,id);if(at<0)changes.append(QJsonObject{{"kind","deleteGroup"},{"groupId",id},{"before",g},{"after",QJsonValue::Null}});else if(!equal(g,next[at]))changes.append(QJsonObject{{"kind","editGroup"},{"groupId",id},{"before",g},{"after",next[at]}});}for(auto v:next){auto g=v.toObject();if(groupIndex(old,g.value("groupId").toString())<0)changes.append(QJsonObject{{"kind","addGroup"},{"groupId",g.value("groupId")},{"before",QJsonValue::Null},{"after",g}});}if(!equal(beforeOrder,afterOrder))changes.append(QJsonObject{{"kind","groupOrder"},{"before",beforeOrder},{"after",afterOrder}});return {{"schema","watchlist-workspace-change/v1"},{"expectedRevision",base.value("revision")},{"expectedFingerprint",fingerprint(base)},{"groups",next},{"mainIds",base.value("mainIds")},{"changes",changes},{"noChange",changes.isEmpty()}};}
inline QJsonObject receipt(QJsonObject base,QJsonObject draft,QJsonObject saved){validate(saved);need(saved.value("revision")!=base.value("revision")&&equal(saved.value("groups"),draft.value("groups"))&&equal(saved.value("mainIds"),base.value("mainIds")),"保存回执未确认请求的完整分组或新版本，未宣称保存成功");auto wanted=management(draft),actual=management(saved);wanted.remove("revision");actual.remove("revision");need(equal(wanted,actual),"保存回执证券目录已变化，未宣称成功");return saved;}
// Host calls while holding its own atomic configuration lock/transaction.
inline QJsonObject acceptChange(QJsonObject current,QJsonObject change,QString nextRevision){validate(current);need(text(change,"schema")=="watchlist-workspace-change/v1"&&text(change,"expectedRevision")==text(current,"revision")&&text(change,"expectedFingerprint")==fingerprint(current),"宿主保存时版本或配置并发变化，未覆盖");auto requested=current;requested["groups"]=change.value("groups");need(equal(prepare(current,requested,current),change),"变更包与权威当前配置不一致，未采用伪造差异");if(change.value("noChange").toBool())return current;need(!nextRevision.trimmed().isEmpty()&&nextRevision!=text(current,"revision"),"保存需明确新配置版本");requested["revision"]=nextRevision;return validate(requested);}
inline QString describe(QJsonObject p){QString out=p.value("noChange").toBool()?"没有配置变化；不会调用保存。\n":"待确认的本机分组变更：\n";for(auto v:p.value("changes").toArray()){auto c=v.toObject();if(c.value("kind")=="groupOrder")out+="组顺序："+canonical(c.value("before"))+" → "+canonical(c.value("after"))+"\n";else{out+=(c.value("kind")=="addGroup"?QString("新建分组"):c.value("kind")=="deleteGroup"?QString("删除分组"):QString("修改分组"))+" · "+c.value("groupId").toString()+"\n";auto a=c.value("before").toObject(),b=c.value("after").toObject();out+="名称："+a.value("name").toString()+" → "+b.value("name").toString()+"\n识别色："+a.value("color").toString()+" → "+b.value("color").toString()+"\n成员及顺序："+canonical(a.value("memberIds"))+" → "+canonical(b.value("memberIds"))+"\n";}}return out+"主自选未删除；其它组成员未连带删除；报价涨跌色未修改。\n";}
}
